package main

import (
	"os"
	"runtime"
	"runtime/pprof"
)

func main() {
	leak := make([][]byte, 0)
	for i := 0; i < 1000; i++ {
		leak = append(leak, make([]byte, 1024)) // live memory that shows in inuse_space
	}
	f, _ := os.Create("mem.out")
	defer f.Close()
	runtime.GC()                            // get up-to-date live stats
	_ = pprof.WriteHeapProfile(f)           // snapshot of the heap
	runtime.KeepAlive(leak)
}
// Analyze churn vs live memory:
//   go tool pprof -sample_index=inuse_space mem.out   (leaks / live bloat)
//   go tool pprof -sample_index=alloc_space mem.out   (GC-pressuring churn)

