package main

import (
	"os"
	"runtime/pprof"
)

// WithCPUProfile guarantees the profile is flushed even if work panics.
func WithCPUProfile(path string, work func()) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	if err := pprof.StartCPUProfile(f); err != nil {
		return err
	}
	defer pprof.StopCPUProfile() // runs during panic unwinding too -> always flushed
	work()                       // runs inside the profiling window
	return nil
}

func main() { _ = WithCPUProfile("cpu.out", func() {}) }

// Explore a collected profile with `go tool pprof`:
//
//   $ go tool pprof -http=:8080 cpu.out   # interactive flame-graph UI in the browser
//
//   $ go tool pprof cpu.out
//   (pprof) top
//         flat  flat%   cum   cum%
//        1.80s 81.8%  1.80s 81.8%  main.fib          # high flat = real self-time hotspot
//        0.05s  2.3%  1.90s 86.4%  encoding/json.Marshal # low flat, high cum = dispatcher
//   (pprof) list main.fib                            # annotated source, line by line
//
// flat = time in the function itself; cum = flat + time in everything it called.

