package solution

import "strings"

func Join(parts []string, sep string) string {
	if len(parts) == 0 {
		return ""
	}
	// Compute the exact final size so Builder grows its buffer once.
	n := len(sep) * (len(parts) - 1)
	for _, p := range parts {
		n += len(p)
	}
	var b strings.Builder
	b.Grow(n) // single allocation of the right size
	for i, p := range parts {
		if i > 0 {
			b.WriteString(sep)
		}
		b.WriteString(p)
	}
	return b.String() // no extra copy: Builder hands over its buffer
}

